import{_ as t,o as r,c as d,a}from"./app.DLPSkIGI.js";const _=JSON.parse('{"title":"MCP Tool Retry Policy","description":"","frontmatter":{},"headers":[],"relativePath":"reference/MCP_RETRY_POLICY.md","filePath":"reference/MCP_RETRY_POLICY.md","lastUpdated":1771753292000}'),o={name:"reference/MCP_RETRY_POLICY.md"};function n(i,e,l,s,c,h){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="mcp-tool-retry-policy" tabindex="-1">MCP Tool Retry Policy <a class="header-anchor" href="#mcp-tool-retry-policy" aria-label="Permalink to &quot;MCP Tool Retry Policy&quot;">​</a></h1><blockquote><p>undefined<strong>Purpose</strong>: Document retry behavior for MCP tools and provider API calls. undefined<strong>Related</strong>: <a href="./../research/ADVANCED_STRATEGIES_AND_RESILIENCE_RESEARCH.html">ADVANCED_STRATEGIES_AND_RESILIENCE_RESEARCH</a>, <a href="./../research/TENACITY_RETRY_AUDIT_PLAN.html">TENACITY_RETRY_AUDIT_PLAN</a></p></blockquote><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Retry Strategy</th><th>Max Attempts</th><th>Backoff</th></tr></thead><tbody><tr><td>undefined<strong>Agent runners</strong> (Codex, Cursor, Direct)</td><td>tenacity <code>@with_retry</code></td><td>2 (cost-aware: API)</td><td>Exponential + jitter (2–30s)</td></tr><tr><td>undefined<strong>Loop controller</strong> (worker)</td><td>tenacity <code>@with_retry</code></td><td>3</td><td>Exponential + jitter</td></tr><tr><td>undefined<strong>State machine</strong> (orchestration)</td><td>tenacity <code>retry()</code></td><td>per-provider</td><td>Exponential + jitter</td></tr><tr><td>undefined<strong>EAGAIN spawn</strong>undefined</td><td>tenacity</td><td>5</td><td>Exponential + jitter (0.1–5s)</td></tr><tr><td>undefined<strong>SIEM egress</strong>undefined</td><td>tenacity</td><td>3</td><td>Exponential + jitter (2–10s)</td></tr><tr><td>undefined<strong>Circuit breaker</strong>undefined</td><td>Per-agent/model</td><td>—</td><td>Blocks when threshold exceeded</td></tr></tbody></table><hr><h2 id="when-we-retry" tabindex="-1">When We Retry <a class="header-anchor" href="#when-we-retry" aria-label="Permalink to &quot;When We Retry&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Retry?</th></tr></thead><tbody><tr><td>503, 504, 502</td><td>Yes</td></tr><tr><td>429 (rate limit)</td><td>Yes</td></tr><tr><td>Timeout, ECONNRESET, ETIMEDOUT</td><td>Yes</td></tr><tr><td>4xx (except 429)</td><td>No</td></tr><tr><td>Usage/quota exhausted</td><td>No (fallback to different provider)</td></tr></tbody></table><hr><h2 id="circuit-breaker" tabindex="-1">Circuit Breaker <a class="header-anchor" href="#circuit-breaker" aria-label="Permalink to &quot;Circuit Breaker&quot;">​</a></h2><p>When <code>THGENT_CIRCUIT_BREAKER_ENABLED=1</code> (default):</p><ul><li>undefined<strong>Threshold</strong>: <code>THGENT_CIRCUIT_BREAKER_THRESHOLD</code> (default 5) failures in <code>THGENT_CIRCUIT_BREAKER_WINDOW_S</code> (default 300s)</li><li>undefined<strong>Recovery</strong>: Half-open after <code>THGENT_CIRCUIT_BREAKER_RECOVERY_S</code> (default 60s)</li><li>undefined<strong>Scope</strong>: Per agent/model; stored in <code>circuit_breakers.jsonl</code></li></ul><hr><h2 id="mcp-tool-invocation" tabindex="-1">MCP Tool Invocation <a class="header-anchor" href="#mcp-tool-invocation" aria-label="Permalink to &quot;MCP Tool Invocation&quot;">​</a></h2><p>MCP tools invoked by clients (Cursor, Claude Code) are executed by thegent&#39;s MCP server. Subprocess tools (e.g. Serena, Octocode) use the agent runners&#39; <code>@with_retry</code> when the runner spawns them. HTTP-based tools rely on the client or underlying library for retries.</p><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p>undefined<strong>Extended on:</strong> 2026-02-17 undefined<strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',24)])])}const E=t(o,[["render",n]]);export{_ as __pageData,E as default};
